def _better(current: int, candidate: int) -> bool:
    return candidate > current

def best_score(scores: list) -> int:
    best = scores[0]
    for s in scores[1:]:
        if _better(best, s):
            best = s
    return best

def worst_score(scores: list) -> int:
    worst = scores[0]
    for s in scores[1:]:
        if not _better(worst, s):
            worst = s
    return worst

